package edu.riara.edp.week07;
import javafx.application.Application;import javafx.scene.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.scene.input.MouseEvent;import javafx.stage.Stage;
public class FiltersHandlersDemo extends Application {public void start(Stage s){TextArea log=new TextArea();Button button=new Button("Click");VBox root=new VBox(10,button,log);root.addEventFilter(MouseEvent.MOUSE_CLICKED,e->log.appendText("Root filter\n"));button.addEventFilter(MouseEvent.MOUSE_CLICKED,e->log.appendText("Button filter\n"));button.addEventHandler(MouseEvent.MOUSE_CLICKED,e->log.appendText("Button handler\n"));root.addEventHandler(MouseEvent.MOUSE_CLICKED,e->log.appendText("Root handler\n"));s.setScene(new Scene(root,450,270));s.show();}public static void main(String[]a){launch(a);}}